#include "stdlib/blas/base/dsymv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/blas/base/dscal.h"
#include "stdlib/blas/ext/base/dfill.h"
#include "stdlib/math/base/special/max.h"

/**
* Performs the matrix-vector operation `Y = alpha*A*X + beta*Y` where `alpha` and `beta` are scalars, `X` and `Y` are `N` element vectors, and `A` is an `N` by `N` symmetric matrix.
*
* @param order         storage layout
* @param uplo          specifies whether the upper or lower triangular part of the symmetric matrix `A` should be referenced
* @param N             number of elements along each dimension of `A`
* @param alpha         scalar constant
* @param A             matrix `A`
* @param LDA           stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param X             first input array
* @param strideX       `X` stride length
* @param offsetX       starting `X` index
* @param beta          scalar constant
* @param Y             second input array
* @param strideY       `Y` stride length
* @param offsetY       starting `Y` index
* @returns				  output value
*/
void API_SUFFIX(c_dsymv_ndarray)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_INT N, const double alpha, const double *A, const CBLAS_INT LDA, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double beta, double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT jmin;
	CBLAS_INT jmax;
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT jx;
	CBLAS_INT jy;
	CBLAS_INT ox;
	CBLAS_INT oy;
	CBLAS_INT i;
	CBLAS_INT j;
	CBLAS_INT k;
	double temp1;
	double temp2;

	// Note on variable naming convention: da#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Perform input argument validation...
	if ( order != CblasColMajor && order != CblasRowMajor ) {
		c_xerbla( 1, "c_dsymv_ndarray", "Error: invalid argument. First argument must be a valid storage order. Value: `%d`.", order );
		return;
	}
	if ( uplo != CblasUpper && uplo != CblasLower ) {
		c_xerbla( 2, "c_dsymv_ndarray", "Error: invalid argument. Second argument must specify whether to reference the lower or upper triangular matrix. Value: `%d`.", uplo );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 3, "c_dsymv_ndarray", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( LDA < API_SUFFIX(stdlib_base_max)( 1, N ) ) {
		c_xerbla( 6, "c_dsymv_ndarray", "Error: invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.", N, LDA );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 8, "c_dsymv_ndarray", "Error: invalid argument. Eighth argument must be a nonzero. Value: `%d`.", strideX );
		return;
	}
	if ( strideY == 0 ) {
		c_xerbla( 12, "c_dsymv_ndarray", "Error: invalid argument. Twelfth argument must be a nonzero. Value: `%d`.", strideY );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( N == 0 || ( alpha == 0.0 && beta == 1.0 ) ) {
		return;
	}
	// Form: y = beta*y
	if ( beta != 1.0 ) {
		if ( beta == 0.0 ) {
			API_SUFFIX(stdlib_strided_dfill_ndarray)( N, 0.0, Y, strideY, offsetY );
		} else {
			API_SUFFIX(c_dscal_ndarray)( N, beta, Y, strideY, offsetY );
		}
	}
	if ( alpha == 0.0 ) {
		return;
	}
	// Form: y = alpha*A*x + y
	ox = offsetX;
	oy = offsetY;

	if (
		( order == CblasRowMajor && uplo == CblasUpper ) ||
		( order == CblasColMajor && uplo == CblasLower )
	) {
		ix = ox;
		iy = oy;
		for ( i = 0; i < N; i++ ) {
			temp1 = alpha * X[ ix ];
			temp2 = 0.0;
			jmin = i + 1;
			jmax = N;
			jx = ox + ( jmin * strideX );
			jy = oy + ( jmin * strideY );
			Y[ iy ] += temp1 * A[ ( LDA * i ) + i ];
			for ( j = jmin; j < jmax; j++ ) {
				k = ( LDA * i ) + j;
				Y[ jy ] += temp1 * A[ k ];
				temp2 += X[ jx ] * A[ k ];
				jx += strideX;
				jy += strideY;
			}
			Y[ iy ] += alpha * temp2;
			ix += strideX;
			iy += strideY;
		}
		return;
	}
	// ( order === 'row-major' && uplo === 'lower') || ( order === 'column-major' && uplo === 'upper' )
	ix = ox + ( ( N - 1 ) * strideX );
	iy = oy + ( ( N - 1 ) * strideY );
	for ( i = N - 1; i >= 0; i-- ) {
		temp1 = alpha * X[ ix ];
		temp2 = 0.0;
		jmin = 0;
		jmax = i;
		jx = ox + ( jmin * strideX );
		jy = oy + ( jmin * strideY );
		Y[ iy ] += temp1 * A[ ( LDA * i ) + i ];
		for ( j = jmin; j < jmax; j++ ) {
			k = ( LDA * i ) + j;
			Y[ jy ] += temp1 * A[ k ];
			temp2 += X[ jx ] * A[ k ];
			jx += strideX;
			jy += strideY;
		}
		Y[ iy ] += alpha * temp2;
		ix -= strideX;
		iy -= strideY;
	}
	return;
}
